mod = 998244353

def inp():
	return int(input())

def st():
	return input().rstrip('\n')

def lis():
	return list(map(int, input().split()))

def ma():
	return map(int, input().split())

def solve(lent, binn):
	runningxor = 0
	beauty = 0
	twopow = 1
	for j in range(lent):
		if not j & 1:
			runningxor ^= int(binn[j])
	runningxor %= mod
	for i in range(lent - 1, -1, -1):
		beauty += runningxor * twopow % mod
		beauty %= mod
		if not i & 1:
			runningxor ^= int(binn[i])
		twopow *= 2
		twopow %= mod
	return beauty

def main():
	for i in range(inp()):
		lent = inp()
		string = st()
		print(solve(lent, string))
main()
